#!/bin/bash
# SessionStart hook — prepare a Claude Code on the web container so `pnpm lint`,
# `pnpm test` and `pnpm --filter @ci-avatar/web build` all work from the first turn.
#
# A fresh cloud session is a bare clone: node_modules is empty and the shared media
# under /assets has not been packed into apps/*/public (those copies are gitignored
# and regenerated by scripts/pack-assets.mjs on predev/prebuild). Without this hook
# the first `pnpm test` in a session fails on missing dependencies.
#
# Runs on the web only — a local checkout is assumed to be set up already.
set -euo pipefail

if [ "${CLAUDE_CODE_REMOTE:-}" != "true" ]; then
  exit 0
fi

cd "${CLAUDE_PROJECT_DIR:-$(dirname "$0")/../..}"

# Chromium is preinstalled in the cloud image at PLAYWRIGHT_BROWSERS_PATH. Tell the
# @playwright/test postinstall not to re-download ~500 MB of browsers it already has.
export PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD=1
export PLAYWRIGHT_BROWSERS_PATH="${PLAYWRIGHT_BROWSERS_PATH:-/opt/pw-browsers}"

# Persist for every later turn in the session, so a Bash call that shells out to
# Playwright directly sees the same paths the install used.
if [ -n "${CLAUDE_ENV_FILE:-}" ]; then
  {
    echo "export PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD=1"
    echo "export PLAYWRIGHT_BROWSERS_PATH=\"$PLAYWRIGHT_BROWSERS_PATH\""
  } >> "$CLAUDE_ENV_FILE"
fi

# pnpm is pinned by package.json#packageManager; corepack honours that pin. The image
# may already ship the right pnpm, so a corepack failure is not fatal on its own.
if command -v corepack >/dev/null 2>&1; then
  corepack enable >/dev/null 2>&1 || echo "[session-start] corepack enable failed; using pnpm from PATH"
fi

if ! command -v pnpm >/dev/null 2>&1; then
  echo "[session-start] pnpm not found on PATH and corepack could not provide it" >&2
  exit 1
fi

echo "[session-start] pnpm $(pnpm -v) / node $(node -v)"

# Plain `pnpm install`, not `--frozen-lockfile`: the container filesystem is cached
# after this hook, so a normal install warms that cache and still resolves from the
# committed lockfile. It also self-heals a lockfile that drifted on a feature branch,
# where a frozen install would hard-fail and leave the session with no dependencies.
# CI keeps `--frozen-lockfile` (.github/workflows/test.yml) — that check is unchanged.
echo "[session-start] installing workspace dependencies..."
pnpm install

# Pack the shared avatar/animation/prop media into apps/web/public. This is also the
# catalog gate, so a genuine asset problem should be visible — but it must not stop the
# session from starting, since lint and most unit tests do not depend on the media.
echo "[session-start] packing shared assets into apps/web/public..."
if ! node scripts/pack-assets.mjs web; then
  echo "[session-start] WARNING: asset packing failed — 'pnpm --filter @ci-avatar/web build' and the e2e suites will not work until it does." >&2
fi

echo "[session-start] ready: pnpm lint | pnpm test | pnpm --filter @ci-avatar/web build"
